public class CountingSheep {
  private boolean asleep;

  synchronized void tryToSleep() {
    while (!isAsleep()) {
      countSomeSheep();
    }
  }

  synchronized boolean isAsleep() {
    return asleep;
  }

  synchronized void setAsleep(boolean value) {
    asleep = value;
  }

  void countSomeSheep() {
    System.out.println("Counting sheep...");
    try {
      Thread.sleep(100);
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }
  }

  public static void main(String[] args) {
    CountingSheep counter = new CountingSheep();

    Thread sheepThread = new Thread(() -> {
      System.out.println("Sheep is trying to sleep...");
      counter.tryToSleep();
      System.out.println("Sheep has fallen asleep.");
    });

    Thread controllerThread = new Thread(() -> {
      try {
        Thread.sleep(200);
        System.out.println("Setting asleep = true");
        counter.setAsleep(true);
      } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
      }
    });

    sheepThread.start();
    controllerThread.start();

    try {
      sheepThread.join();
      controllerThread.join();
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }

    System.out.println("Main thread finished.");
  }
}

