public class ScoutDrift {

    private static volatile boolean asleep = false;

    public static void main(String[] args) {
        Thread sleeperThread = new Thread(new SleepTask());
        sleeperThread.start();

        try {
            // Simulate the main thread doing other tasks briefly
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        asleep = true; // Wake up the sleeping scout

        try {
            sleeperThread.join(); // Wait for the sleep task to finish
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static class SleepTask implements Runnable {

        @Override
        public void run() {
            tryToSleep();
        }

        private void tryToSleep() {
            while (!asleep) {
                countSomeSheep();
            }
        }

        private void countSomeSheep() {
            System.out.println("Observing fireflies...");
            try {
                Thread.sleep(500); // Simulate time taken to observe
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}
