                               long timeout, TimeUnit unit) {
        try (ReentrantLock sourceLock = sourceLocker.getLock(),
                         targetLock = targetLocker.getLock()) {

            long deadline = System.currentTimeMillis() + unit.toMillis(timeout);

            while (System.currentTimeMillis() < deadline) {
                if (sourceLock.tryLock()) {
                    try {
                        if (targetLock.tryLock()) {
                            return attemptMove(sourceLocker, targetLocker, quantity);
                        }
                    } finally {
                        sourceLock.unlock();
                    }

                    long delay = calculateRandomDelay(unit.toMillis(timeout));
                    try {
