public class DeadlockAvoidanceSwap {

    static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }

    static class ElementCount {
        private int count;

        public ElementCount(int initialCount) {
            this.count = initialCount;
        }

        public synchronized void add(int value) {
            count += value;
        }

        public synchronized void remove(int value) throws InsufficientElementsException {
            if (count < value) {
                throw new InsufficientElementsException("Insufficient elements to remove");
            }
            count -= value;
        }

        public int getCount() {
            return count;
        }
    }

    static class Container {
        private final ReentrantLock lock = new ReentrantLock();
        private ElementCount elementCount;

        public Container(int initialCount) {
            this.elementCount = new ElementCount(initialCount);
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public ElementCount getElementCount() {
            return elementCount;
        }
    }

    public static boolean swap(Container origin, Container target, int elementsToSwap,
                               long timeout, TimeUnit unit) throws InterruptedException {
        Random random = new Random();
        for (int attempt = 0; attempt < 10; attempt++) {
            if (origin.getLock().tryLock(timeout, unit)) {
                try {
                    if (target.getLock().tryLock(timeout, unit)) {
                        try {
                            if (origin.getElementCount().getCount() >= elementsToSwap) {
                                origin.getElementCount().remove(elementsToSwap);
                                target.getElementCount().add(elementsToSwap);
                                return true;
                            } else {
                                throw new InsufficientElementsException("Not enough elements in the origin container");
                            }
                        } finally {
                            target.getLock().unlock();
                        }
                    }
                } finally {
                    origin.getLock().unlock();
                }
            }

            long fixedDelay = 100; // milliseconds
            long randomDelay = 50 + random.nextInt(51); // milliseconds
            TimeUnit.MILLISECONDS.sleep(fixedDelay + randomDelay);
        }
        return false;
    }

    public static void main(String[] args) throws InterruptedException {
        Container containerA = new Container(10);
        Container containerB = new Container(5);

        Runnable task1 = () -> {
            try {
                while (!swap(containerA, containerB, 3, 2, TimeUnit.SECONDS)) {
                    System.out.println("Task 1: Swap attempt failed");
                }
                System.out.println("Task 1: Swap successful");
