                try {
                    if (target.tryAcquire(timeout, timeUnit)) {
                        try {
                            if (origin.getElementCount() >= elementsToSwap) {
                                origin.decreaseElementCount(elementsToSwap);
                                target.increaseElementCount(elementsToSwap);
                                return true;
                            } else {
