public class SwapContainers {

    public static void main(String[] args) {
        Container containerA = new Container();
        Container containerB = new Container();

        // Add some elements to containerA for testing
        containerA.addElement(new ElementCount(1));
        containerA.addElement(new ElementCount(2));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable swapTask = () -> {
