            System.out.println("Swap successful: " + result);
        };

        executor.submit(swapTask);
        executor.submit(swapTask);

        executor.shutdown();
    }

    public static boolean swap(Container origin, Container target, int elementsToSwap, long timeout, TimeUnit timeUnit) {
        ReentrantLock originLock = new ReentrantLock();
        ReentrantLock targetLock = new ReentrantLock();

        try {
            if (originLock.tryLock(timeout, timeUnit)
                    && targetLock.tryLock(timeout, timeUnit)) {

                if (origin.getNumberOfElements() >= elementsToSwap) {
                    // Perform the swap
                    for (int i = 0; i < elementsToSwap; i++) {
                        ElementCount element = origin.removeElement();
                        target.addElement(element);
                    }
                    return true;
                } else {
                    throw new InsufficientElementsException("Not enough elements to swap.");
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            if (originLock.isHeldByCurrentThread()) originLock.unlock();
            if (targetLock.isHeldByCurrentThread()) targetLock.unlock();
        }

        return false;
    }

    private static long calculateFixedDelay() {
        // Fixed delay component
        return 100L; // milliseconds
    }

    private static long calculateRandomDelay() {
        // Random delay component
        Random random = new Random();
        return 50 + (long) (random.nextDouble() * 150); // between 50 and 200 milliseconds
    }

    public static class Container {
        private final List<ElementCount> elements = new ArrayList<>();
        private final ReentrantLock lock = new ReentrantLock();

        public void addElement(ElementCount element) {
            lock.lock();
            try {
                elements.add(element);
            } finally {
                lock.unlock();
            }
        }

        public ElementCount removeElement() {
            lock.lock();
            try {
                if (elements.isEmpty()) throw new InsufficientElementsException("No elements to remove.");
                return elements.remove(elements.size() - 1);
            } finally {
                lock.unlock();
            }
        }

        public int getNumberOfElements() {
            lock.lock();
            try {
                return elements.size();
            } finally {
                lock.unlock();
            }
        }
    }

    public static class ElementCount {
