            this.elementCount = new ElementCount(this.elementCount.getCount() - decrement);
        }

        public void increaseElementCount(int increment) {
            // This should be synchronized with a lock to ensure thread safety
            this.elementCount = new ElementCount(this.elementCount.getCount() + increment);
        }
    }

