import java.util.concurrent.locks.*;

public class WidgetMover {

    static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }

    static class Bin {
        private final ReentrantLock lock = new ReentrantLock();
        private int widgetCount;

        Bin(int initialWidgets) {
            this.widgetCount = initialWidgets;
        }

        void addWidgets(int count) {
            if (lock.tryLock()) {
                try {
                    widgetCount += count;
                } finally {
                    lock.unlock();
                }
            }
        }

        boolean removeWidgets(int count, NotEnoughWidgetsException exception) throws InterruptedException {
            boolean acquired = lock.tryLock();
            while (!acquired) {
                if (lock.tryLock(1, TimeUnit.SECONDS)) {
                    acquired = true;
                } else {
                    Thread.sleep(calculateRandomDelay());
                }
            }
            try {
                if (widgetCount >= count) {
                    widgetCount -= count;
                    return true;
                } else {
                    exception.message = "Not enough widgets in the bin.";
                    throw exception;
                }
            } finally {
                lock.unlock();
            }
        }

        int getWidgetCount() {
            return widgetCount;
        }
    }

    static class WidgetCount {
        private final Bin source;
        private final Bin target;
        private final int numWidgetsToMove;
        private final long timeoutDuration;
        private final TimeUnit timeUnit;

        WidgetCount(Bin source, Bin target, int numWidgetsToMove, long timeoutDuration, TimeUnit timeUnit) {
            this.source = source;
            this.target = target;
            this.numWidgetsToMove = numWidgetsToMove;
            this.timeoutDuration = timeoutDuration;
            this.timeUnit = timeUnit;
        }

        boolean move() throws NotEnoughWidgetsException, InterruptedException {
            NotEnoughWidgetsException exception = new NotEnoughWidgetsException("");
            boolean sourceLocked = false, targetLocked = false;

            long startTime = System.nanoTime();
            while ((System.nanoTime() - startTime) < TimeUnit.NANOSECONDS.convert(timeoutDuration, timeUnit)) {
                if (source.lock.tryLock()) {
                    try {
                        if (target.lock.tryLock()) {
                            try {
                                sourceLocked = true;
                                targetLocked = true;

                                if (source.getWidgetCount() >= numWidgetsToMove) {
                                    source.removeWidgets(numWidgetsToMove, exception);
                                    target.addWidgets(numWidgetsToMove);
                                    return true;
                                } else {
                                    throw exception;
                                }
                            } finally {
                                if (targetLocked) target.lock.unlock();
                            }
                        }
                    } finally {
                        if (sourceLocked) source.lock.unlock();
                    }
                }

                Thread.sleep(calculateRandomDelay());
            }

            return false;
        }
    }

    private static long calculateFixedDelay(long timeoutDuration, TimeUnit timeUnit) {
        return timeUnit.toNanos(timeoutDuration) / 10;
    }

    private static long calculateRandomDelay() {
        return (long) (Math.random() * calculateFixedDelay(1, TimeUnit.SECONDS));
    }

    public static void main(String[] args) throws InterruptedException {
        final int initialWidgets = 100;
        final int widgetsToMove = 50;
        final long timeoutDuration = 5; // seconds
        Bin sourceBin = new Bin(initialWidgets);
        Bin targetBin = new Bin(0);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Runnable moverTask1 = () -> {
            try {
                WidgetCount widgetCount1 = new WidgetCount(sourceBin, targetBin, widgetsToMove, timeoutDuration, TimeUnit.SECONDS);
                boolean success = widgetCount1.move();
                System.out.println("Thread 1 move successful: " + success);
            } catch (NotEnoughWidgetsException | InterruptedException e) {
                System.err.println(e.getMessage());
            }
        };

        Runnable moverTask2 = () -> {
            try {
                WidgetCount widgetCount2 = new WidgetCount(targetBin, sourceBin, widgetsToMove, timeoutDuration, TimeUnit.SECONDS);
                boolean success = widgetCount2.move();
                System.out.println("Thread 2 move successful: " + success);
            } catch (NotEnoughWidgetsException | InterruptedException e) {
                System.err.println(e.getMessage());
            }
        };

        executor.execute(moverTask1);
        executor.execute(moverTask2);

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);
    }
