import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.util.Random;
import java.time.Duration;

public class WidgetMover {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Bin sourceBin = new Bin("Source", 50);
        Bin targetBin = new Bin("Target", 30);

        Runnable task1 = () -> moveWidgets(sourceBin, targetBin, 20, Duration.ofSeconds(5), TimeUnit.SECONDS);
        Runnable task2 = () -> moveWidgets(targetBin, sourceBin, 15, Duration.ofSeconds(5), TimeUnit.SECONDS);

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
    }

    public static boolean moveWidgets(Bin source, Bin target, int count, Duration timeout, TimeUnit timeUnit) {
        Lock lockSource = new ReentrantLock();
        Lock lockTarget = new ReentrantLock();

        long timeoutMillis = timeout.toMillis();

        while (timeoutMillis > 0) {
            if (lockSource.tryLock(timeoutMillis, TimeUnit.MILLISECONDS)
                    && lockTarget.tryLock(timeoutMillis, TimeUnit.MILLISECONDS)) {

                try {
                    if (source.getWidgets() >= count) {
                        source.decrement(count);
                        target.increment(count);
                        return true;
                    } else {
                        throw new NotEnoughWidgetsException("Not enough widgets in the source bin.");
                    }
                } finally {
                    lockSource.unlock();
                    lockTarget.unlock();
                }
            } else {
                timeoutMillis -= calculateRandomDelay(Duration.ofMillis(50), Duration.ofMillis(100));
                Thread.yield(); // Allow other threads to run
            }
        }

        return false;
    }

    private static long calculateFixedDelay(Duration fixedDelay) {
        return fixedDelay.toNanos();
    }

    private static long calculateRandomDelay(Duration min, Duration max) {
        Random random = new Random();
        long minMillis = min.toMillis();
        long maxMillis = max.toMillis();
        return minMillis + (long) (random.nextDouble() * (maxMillis - minMillis));
    }

    static class Bin {
        private final String name;
        private WidgetCount widgetCount;

        public Bin(String name, int initialWidgets) {
            this.name = name;
            this.widgetCount = new WidgetCount(initialWidgets);
        }

        public void increment(int count) {
            synchronized (widgetCount) {
                widgetCount.count += count;
            }
        }

        public void decrement(int count) {
            synchronized (widgetCount) {
                widgetCount.count -= count;
            }
        }

        public int getWidgets() {
            synchronized (widgetCount) {
                return widgetCount.count;
            }
        }

        @Override
        public String toString() {
            return name + ": " + getWidgets();
        }
    }

    static class WidgetCount {
        volatile int count;

        public WidgetCount(int initialCount) {
            this.count = initialCount;
        }
    }

    static class NotEnoughWidgetsException extends RuntimeException {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }
}
