import java.util.concurrent.*;
import java.util.Random;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class WidgetMover {

    public static void main(String[] args) {
        Bin bin1 = new Bin("Bin1", 100);
        Bin bin2 = new Bin("Bin2", 50);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> moveWidgets(bin1, bin2, 30, 500, TimeUnit.MILLISECONDS);
        Runnable task2 = () -> moveWidgets(bin2, bin1, 20, 500, TimeUnit.MILLISECONDS);

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
    }

    public static boolean moveWidgets(Bin source, Bin target, int count, long timeout, TimeUnit unit) {
        Lock lock1 = new ReentrantLock();
        Lock lock2 = new ReentrantLock();

        long timeoutMillis = unit.toMillis(timeout);

        while (true) {
            long start = System.currentTimeMillis();
            if (lock1.tryLock() && lock2.tryLock()) {
                try {
                    if (source.widgets >= count) {
                        source.widgets -= count;
                        target.widgets += count;
                        return true;
                    } else {
                        throw new NotEnoughWidgetsException(source.name, count - source.widgets);
                    }
                } finally {
                    lock1.unlock();
                    lock2.unlock();
                }
            }

            long elapsed = System.currentTimeMillis() - start;

            if (elapsed >= timeoutMillis) {
                return false;
            }

            long delay = calculateFixedDelay(elapsed, timeoutMillis) + calculateRandomDelay();

            try {
                Thread.sleep(delay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
        }
    }

    private static long calculateFixedDelay(long elapsed, long totalTimeout) {
        double ratio = ((double) elapsed / totalTimeout);
        return (long) (totalTimeout * (1 - ratio));
    }

    private static long calculateRandomDelay() {
        Random random = new Random();
        return random.nextInt(100); // Random delay between 0 and 99 milliseconds
    }

    public static class Bin {
        String name;
        int widgets;

        public Bin(String name, int widgets) {
            this.name = name;
            this.widgets = widgets;
        }
    }

    public static class NotEnoughWidgetsException extends RuntimeException {
        private final String binName;
        private final int shortage;

        public NotEnoughWidgetsException(String binName, int shortage) {
            super("Not enough widgets in " + binName + ". Shortage: " + shortage);
            this.binName = binName;
            this.shortage = shortage;
        }
    }

    public static class WidgetCount {
        private final int count;

        public WidgetCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }
    }
}
