public class PublishingVehicleTracker {
    private final Map<String, SafePoint> vehicleCoordinates = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        PublishingVehicleTracker tracker = new PublishingVehicleTracker();

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> tracker.updateVehicle("car1", 10, 20));
        executor.submit(() -> tracker.updateVehicle("car2", 30, 40));

        executor.shutdown();

        try {
            while (!executor.isTerminated()) {
                // Wait for all tasks to finish
            }
        } catch (InterruptedException e) {
