import java.util.*;
import java.util.concurrent.*;

public class RuneHarmonizer {

    enum Constellation {
        FIRE, WATER, EARTH, AIR
    }

    enum Resonance {
        POSITIVE, NEGATIVE
    }

    static class Rune {
        private final Constellation constellation;
        private final Resonance resonance;

        public Rune(Constellation constellation, Resonance resonance) {
            this.constellation = constellation;
            this.resonance = resonance;
        }

        public Constellation getConstellation() {
            return constellation;
        }

        public Resonance getResonance() {
            return resonance;
        }
    }

    static class Harmony {
        private final Rune rune1;
        private final Rune rune2;

        public Harmony(Rune rune1, Rune rune2) {
            this.rune1 = rune1;
            this.rune2 = rune2;
        }

        @Override
        public String toString() {
            return "Harmony{" + rune1.getConstellation() + rune1.getResonance() +
                    " <-> " + rune2.getConstellation() + rune2.getResonance() + '}';
        }
    }

    static class Grimoire {
        private final List<Harmony> harmonies = new ArrayList<>();

        public synchronized void crystallize(Harmony harmony) {
            harmonies.add(harmony);
        }

        public int getNumberOfHarmonies() {
            return harmonies.size();
        }

        @Override
        public String toString() {
            return "Grimoire{" + harmonies + '}';
        }
    }

    private static int channelTheGrimoire(Collection<Rune> runes) throws InterruptedException, ExecutionException {
        Grimoire grimoire = new Grimoire();

        List<Rune> sortedRunes = new ArrayList<>(runes);
        sortedRunes.sort(Comparator.comparing(Rune::getConstellation)
                .thenComparing(r -> r.getResonance() == Resonance.POSITIVE ? 0 : 1));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<?>> futures = new ArrayList<>();

        for (int i = 0; i < sortedRunes.size(); i += 2) {
            Rune rune1 = sortedRunes.get(i);
            if (i + 1 >= sortedRunes.size()) break;

            Rune rune2 = sortedRunes.get(i + 1);

            if (rune1.getConstellation() == rune2.getConstellation()
                    && rune1.getResonance() != rune2.getResonance()) {

                final Harmony harmony = new Harmony(rune1, rune2);
                Future<?> future = executor.submit(() -> grimoire.crystallize(harmony));
                futures.add(future);
            }
        }

        for (Future<?> future : futures) {
            future.get();
        }

        executor.shutdown();

        return grimoire.getNumberOfHarmonies();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Rune> runes = Arrays.asList(
                new Rune(Constellation.FIRE, Resonance.POSITIVE),
                new Rune(Constellation.FIRE, Resonance.NEGATIVE),
                new Rune(Constellation.WATER, Resonance.POSITIVE),
                new Rune(Constellation.WATER, Resonance.NEGATIVE),
                new Rune(Constellation.EARTH, Resonance.POSITIVE),
                new Rune(Constellation.AIR, Resonance.NEGATIVE)
        );

        int harmonies = channelTheGrimoire(runes);
        System.out.println("Number of harmonies: " + harmonies);
    }
}

