        public int compareTo(Rune other) {
            int constellationComparison = this.constellation.compareTo(other.constellation);
            if (constellationComparison != 0) {
                return constellationComparison;
            }
            return this.resonance == Resonance.POSITIVE ? -1 : 1;
        }

        @Override
        public String toString() {
            return name + "(" + constellation + ", " + resonance + ")";
        }
    }

