        private final List<Rune> runes;

        public Harmony(List<Rune> runes) {
            this.runes = runes;
        }

        @Override
        public Integer call() throws Exception {
            int harmoniesCount = 0;
            for (int i = 0; i < runes.size() - 1; i++) {
                Rune rune1 = runes.get(i);
                Rune rune2 = runes.get(i + 1);

                if (rune1.getConstellation().equals(rune2.getConstellation()) &&
                        rune1.getResonance() != rune2.getResonance()) {
                    harmoniesCount++;
                    i++; // Skip next rune as it's already paired
                }
            }
            return harmoniesCount;
        }
    }

