import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class Whisker implements Runnable {
    private final int spark;
    private final int glimmer;

    public Whisker(int spark, int glimmer) {
        this.spark = spark;
        this.glimmer = glimmer;
    }

    @Override
    public void run() {
        // Simulate some concurrent work with the whisker
        System.out.println("Running in thread: " + Thread.currentThread().getName());
        System.out.printf("Whisker at position (%d, %d)%n", this.spark, this.glimmer);
    }

    private static class WhiskerCreator implements Runnable {
        @Override
        public void run() {
            ExecutorService executor = Executors.newFixedThreadPool(5);

            for (int i = 0; i < 10; i++) {
                int spark = i * 2;
                int glimmer = i * 3;
                Whisker whisker = new Whisker(spark, glimmer);
                executor.submit(whisker);
            }

            executor.shutdown();
        }
    }

    public static void main(String[] args) {
        Thread creatorThread = new Thread(new WhiskerCreator());
        creatorThread.start();

        try {
            creatorThread.join(); // Wait for the creator thread to finish
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
