import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.Collections;

class MysticBeastTracker {
    private final ConcurrentHashMap<String, Glyph> perches = new ConcurrentHashMap<>();

    public MysticBeastTracker(Map<String, Glyph> initialPerches) {
        perches.putAll(initialPerches);
    }

    public Map<String, Glyph> getPerches() {
        return Collections.unmodifiableMap(perches);
    }

    public Glyph getPerch(String sigil) {
        return perches.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) throws IllegalArgumentException {
        if (!perches.containsKey(sigil)) {
            throw new IllegalArgumentException("Beast with sigil " + sigil + " does not exist.");
        }
        perches.put(sigil, new Glyph(spark, glimmer));
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(perches));
    }

    static class Glyph {
        private final int spark;
        private final int glimmer;

        public Glyph(int spark, int glimmer) {
            this.spark = spark;
            this.glimmer = glimmer;
        }

        @Override
        public String toString() {
            return "Glyph{" +
                    "spark=" + spark +
                    ", glimmer=" + glimmer +
                    '}';
        }
    }

    public static void main(String[] args) {
        Map<String, Glyph> initialPerches = Map.of(
                "Phoenix", new Glyph(10, 20),
                "Griffin", new Glyph(30, 40)
        );

        MysticBeastTracker tracker = new MysticBeastTracker(initialPerches);

        ExecutorService executor = Executors.newFixedThreadPool(5);

        Runnable task1 = () -> {
            try {
                System.out.println("Task 1: Setting Phoenix perch to (50, 60)");
                tracker.setPerch("Phoenix", 50, 60);
            } catch (IllegalArgumentException e) {
                System.err.println(e.getMessage());
            }
        };

        Runnable task2 = () -> {
            try {
                System.out.println("Task 2: Attempting to set Dragon perch");
                tracker.setPerch("Dragon", 70, 80);
            } catch (IllegalArgumentException e) {
                System.err.println(e.getMessage());
            }
        };

        Runnable task3 = () -> {
            System.out.println("Task 3: Getting Phoenix perch");
            Glyph phoenixPerch = tracker.getPerch("Phoenix");
            System.out.println(phoenixPerch);
        };

        Runnable task4 = () -> {
            System.out.println("Task 4: Getting all perches");
            Map<String, Glyph> perches = tracker.getPerches();
            perches.forEach((sigil, glyph) -> System.out.println(sigil + ": " + glyph));
        };

