import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.LinkedBlockingQueue;

public class Enchantment {

    interface Talisman {
        int enchant();
    }

    static class SimpleTalisman implements Talisman {
        private final int id;

        public SimpleTalisman(int id) {
            this.id = id;
        }

        @Override
        public int enchant() {
            return id * 2; // Example enchantment process
        }
    }

    interface SigilNode<T> {
        T compute();
        List<SigilNode<T>> getChildren();
    }

    static class TalismanSigilNode implements SigilNode<Integer> {
        private final Talisman talisman;
        private final List<SigilNode<Integer>> children;

        public TalismanSigilNode(Talisman talisman, List<SigilNode<Integer>> children) {
            this.talisman = talisman;
            this.children = children;
        }

        @Override
        public Integer compute() {
            return talisman.enchant();
        }

        @Override
        public List<SigilNode<Integer>> getChildren() {
            return children;
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            // Example usage
            Talisman talisman1 = new SimpleTalisman(1);
            Talisman talisman2 = new SimpleTalisman(2);

            List<Talisman> talismans = List.of(talisman1, talisman2);
            LinkedBlockingQueue<Integer> sequentialResults = new LinkedBlockingQueue<>();
            weaveSequentially(talismans, sequentialResults);

            System.out.println("Sequential Results: " + sequentialResults);

            LinkedBlockingQueue<Integer> parallelResults = new LinkedBlockingQueue<>();
            dispatchParallel(talismans, executor, parallelResults);

            // Wait for all tasks to complete
            executor.shutdown();
            while (!executor.isTerminated()) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }

            System.out.println("Parallel Results: " + parallelResults);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void weaveSequentially(List<Talisman> talismans, LinkedBlockingQueue<Integer> results) {
        for (Talisman talisman : talismans) {
            int result = talisman.enchant();
            results.add(result);
        }
    }

    public static void dispatchParallel(List<Talisman> talismans, ExecutorService executor, LinkedBlockingQueue<Integer> results) {
        List<Future<?>> futures = new ArrayList<>();
        for (Talisman talisman : talismans) {
            Callable<Void> task = () -> {
                int result = talisman.enchant();
                results.add(result);
                return null;
            };
            futures.add(executor.submit(task));
        }
        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void weaveSequentiallyRecursive(SigilNode<Integer> node, LinkedBlockingQueue<Integer> results) {
        results.add(node.compute());
        for (SigilNode<Integer> child : node.getChildren()) {
            weaveSequentiallyRecursive(child, results);
        }
    }

    public static void dispatchParallelRecursive(SigilNode<Integer> node, ExecutorService executor, LinkedBlockingQueue<Integer> results) {
        Callable<Void> task = () -> {
            int result = node.compute();
            results.add(result);
            List<SigilNode<Integer>> children = node.getChildren();
            for (SigilNode<Integer> child : children) {
                dispatchParallelRecursive(child, executor, results);
            }
            return null;
        };
        executor.submit(task);
    }
}

