class SimpleSigilNode<T extends Talisman> implements SigilNode<T> {
    private final T talisman;
    private final List<SigilNode<T>> childNodes;

    public SimpleSigilNode(T talisman, List<SigilNode<T>> childNodes) {
        this.talisman = talisman;
        this.childNodes = childNodes;
    }

