public class EnchantmentProcessor {

    private static final ExecutorService executor = Executors.newFixedThreadPool(2);

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Talisman> talismans = Arrays.asList(
                new SimpleTalisman(1),
                new SimpleTalisman(2),
                new SimpleTalisman(3)
        );

        System.out.println("Sequential processing result: " + processSequential(talismans));

        System.out.println("Parallel processing result: " + processParallel(talismans));

        SigilNode<Talisman> root = new SimpleSigilNode<>(
                new SimpleTalisman(0),
                Arrays.asList(
                        new SimpleSigilNode<>(new SimpleTalisman(1), Collections.emptyList()),
                        new SimpleSigilNode<>(new SimpleTalisman(2), Collections.emptyList())
                )
        );

        System.out.println("Sequential recursive processing result: " + processRecursiveSequential(root));
        System.out.println("Parallel recursive processing result: " + processRecursiveParallel(root));

        executor.shutdown();
    }

    public static List<Integer> processSequential(List<Talisman> talismans) {
        List<Integer> results = new ArrayList<>();
        for (Talisman talisman : talismans) {
            results.add(talisman.enchant());
        }
        return results;
    }

    public static List<Integer> processParallel(List<Talisman> talismans) throws InterruptedException, ExecutionException {
        List<Future<Integer>> futures = new ArrayList<>();
        for (Talisman talisman : talismans) {
            futures.add(executor.submit(() -> talisman.enchant()));
        }
        List<Integer> results = new ArrayList<>();
        for (Future<Integer> future : futures) {
            results.add(future.get());
        }
        return results;
    }

    public static int processRecursiveSequential(SigilNode<Talisman> node) {
        int result = node.compute().enchant();
        for (SigilNode<Talisman> child : node.children()) {
            result += processRecursiveSequential(child);
        }
        return result;
    }

    public static int processRecursiveParallel(SigilNode<Talisman> node) throws InterruptedException, ExecutionException {
        Future<Integer> currentFuture = executor.submit(() -> node.compute().enchant());
        List<Future<Integer>> childFutures = new ArrayList<>();
        for (SigilNode<Talisman> child : node.children()) {
            childFutures.add(executor.submit(() -> processRecursiveParallel(child)));
        }
        int result = currentFuture.get();
        for (Future<Integer> future : childFutures) {
            result += future.get();
        }
        return result;
    }
}

