import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

interface Charm {
    void cast();
}

interface RuneNode<T> {
    T computeValue();
    List<RuneNode<T>> getChildren();
}

public class Spellcaster {

    public static <T> void processSequentially(List<Charm> charms) {
        for (Charm charm : charms) {
            charm.cast();
        }
    }

    public static <T> void processConcurrently(List<Charm> charms, ExecutorService executor) {
        List<Future<?>> futures = new ArrayList<>();
        for (Charm charm : charms) {
            futures.add(executor.submit(() -> charm.cast()));
        }
        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static <T> T processRuneNodeSequentially(RuneNode<T> rootNode, Runnable<T> accumulator) {
        accumulator.run(rootNode.computeValue());
        for (RuneNode<T> child : rootNode.getChildren()) {
            processRuneNodeSequentially(child, accumulator);
        }
        return null;
    }

    public static <T> T processRuneNodesConcurrently(RuneNode<T> rootNode, ExecutorService executor) throws InterruptedException, ExecutionException {
        List<Future<?>> futures = new ArrayList<>();
        futures.add(executor.submit(() -> rootNode.computeValue()));
        for (RuneNode<T> child : rootNode.getChildren()) {
            futures.add(executor.submit(() -> processRuneNodesConcurrently(child, executor)));
        }
        T result = null;
        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                throw e;
            }
        }
        return result;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        List<Charm> charms = new ArrayList<>();
        charms.add(() -> System.out.println("Casting Charm 1"));
        charms.add(() -> System.out.println("Casting Charm 2"));

