import java.util.concurrent.TimeUnit;

interface Charm {
    void invoke();
}

class SampleCharm implements Charm {
    private final int id;

    public SampleCharm(int id) {
        this.id = id;
    }

    @Override
    public void invoke() {
        System.out.println("Charm " + id + " invoked");
    }
}

interface RuneNode<T> {
    T compute();
    List<RuneNode<T>> getChildren();
}

class CharmedRuneNode implements RuneNode<Integer>, Charm {
    private final int value;
    private final List<CharmedRuneNode> children;

    public CharmedRuneNode(int value) {
        this.value = value;
        this.children = new ArrayList<>();
    }

    @Override
    public Integer compute() {
        return value + children.stream().mapToInt(RuneNode::compute).sum();
    }

    @Override
    public List<RuneNode<Integer>> getChildren() {
        return children;
    }

    @Override
    public void invoke() {
        System.out.println("Charm with value " + value + " invoked");
    }

    public void addChild(CharmedRuneNode child) {
        children.add(child);
    }
}

public class ConcurrentSpellcasting {

    private static void processCharmsSequentially(List<Charm> charms) {
        for (Charm charm : charms) {
            charm.invoke();
        }
    }

    private static List<Future<?>> processCharmsConcurrently(List<Charm> charms, ExecutorService executor) {
        List<Future<?>> futures = new ArrayList<>();
        for (Charm charm : charms) {
            Future<?> future = executor.submit(() -> charm.invoke());
            futures.add(future);
        }
        return futures;
    }

    private static Integer processRuneNodesSequentially(RuneNode<Integer> root) {
        Integer result = root.compute();
        for (RuneNode<Integer> child : root.getChildren()) {
            result += processRuneNodesSequentially(child);
        }
        return result;
    }

    private static List<Future<?>> processRuneNodesConcurrently(RuneNode<Integer> root, ExecutorService executor) {
        List<Future<?>> futures = new ArrayList<>();
        futures.add(executor.submit(() -> root.compute()));

        for (RuneNode<Integer> child : root.getChildren()) {
            futures.addAll(processRuneNodesConcurrently(child, executor));
        }
        return futures;
    }

    private static void waitForCompletion(List<Future<?>> futures) {
        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) throws Exception {
        List<Charm> charms = new ArrayList<>();
        charms.add(new SampleCharm(1));
        charms.add(new SampleCharm(2));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        System.out.println("Sequential Charm Processing:");
        processCharmsSequentially(charms);

        System.out.println("\nConcurrent Charm Processing:");
        List<Future<?>> charmFutures = processCharmsConcurrently(charms, executor);
        waitForCompletion(charmFutures);
        executor.shutdown();

        CharmedRuneNode root = new CharmedRuneNode(10);
        CharmedRuneNode child1 = new CharmedRuneNode(5);
        CharmedRuneNode child2 = new CharmedRuneNode(3);

        root.addChild(child1);
        root.addChild(child2);

        System.out.println("\nSequential Rune Node Processing Result: " + processRuneNodesSequentially(root));

        executor = Executors.newFixedThreadPool(2);

        System.out.println("\nConcurrent Rune Node Processing:");
        List<Future<?>> runeFutures = processRuneNodesConcurrently(root, executor);
        waitForCompletion(runeFutures);
        executor.shutdown();
    }
}

