    public VaultImpl(int id, int initialGold) {
        this.id = id;
        this.gold = initialGold;
    }

    @Override
    public void deposit(int gold) {
        synchronized (this) {
            this.gold += gold;
        }
    }

    @Override
    public int withdraw(int gold) throws InsufficientTreasureException {
        synchronized (this) {
            if (gold > this.gold) {
                throw new InsufficientTreasureException("Not enough treasure in vault " + id);
            }
            this.gold -= gold;
            return gold;
        }
    }

    @Override
    public int get() {
        synchronized (this) {
