    private static void transfer(Vault fromVault, Vault toVault, int amount) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            try {
                synchronized (determineLockOrder(fromVault, toVault)) {
                    if (fromVault.get() >= amount) {
                        synchronized (toVault) {
                            fromVault.withdraw(amount);
                            toVault.deposit(amount);
                        }
                    }
                }
            } catch (InsufficientTreasureException e) {
                System.out.println(e.getMessage());
            }
        };

        Runnable task2 = () -> {
            try {
                synchronized (determineLockOrder(toVault, fromVault)) {
                    if (toVault.get() >= amount) {
                        synchronized (fromVault) {
                            toVault.withdraw(amount);
                            fromVault.deposit(amount);
                        }
                    }
                }
            } catch (InsufficientTreasureException e) {
                System.out.println(e.getMessage());
