class PotionLoop {
    private final Object[] buffer;
    private int count, in, out;
    private final Semaphore empty, full;

    public PotionLoop(int size) {
        buffer = new Object[size];
        this.count = 0;
        in = 0;
        out = 0;
        empty = new Semaphore(size);
        full = new Semaphore(0);
