import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class CrystalCache<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public CrystalCache(Map<K, V> initialMap) {
        this.map = new HashMap<>(initialMap);
    }

    public V get(K key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean put(K key, V value) {
        lock.writeLock().lock();
        try {
            return map.put(key, value) != null;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V remove(K key) {
        lock.writeLock().lock();
        try {
            return map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        lock.writeLock().lock();
        try {
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(K key) {
        lock.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(V value) {
        lock.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) {
        Map<String, String> initialMap = new HashMap<>();
        initialMap.put("relic1", "power1");
        CrystalCache<String, String> cache = new CrystalCache<>(initialMap);

        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable readTask = () -> {
            for (int i = 0; i < 10; i++) {
                System.out.println("Reading: " + cache.get("relic1"));
            }
        };

        Runnable writeTask = () -> {
            for (int i = 0; i < 5; i++) {
