import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.HashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EnchantedRegistry {

    private final Map<String, String> artifactsMap;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public EnchantedRegistry(Map<String, String> existingArtifacts) {
        this.artifactsMap = new HashMap<>(existingArtifacts);
    }

    public String get(String key) {
        lock.readLock().lock();
        try {
            return artifactsMap.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void put(String key, String value) {
        lock.writeLock().lock();
        try {
            artifactsMap.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void remove(Object key) {
        lock.writeLock().lock();
        try {
            artifactsMap.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        lock.readLock().lock();
        try {
            return artifactsMap.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        lock.readLock().lock();
        try {
            return artifactsMap.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return artifactsMap.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return artifactsMap.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public void putAll(Map<? extends String, ? extends String> m) {
        lock.writeLock().lock();
        try {
            artifactsMap.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            artifactsMap.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public static void main(String[] args) {
        Map<String, String> initialArtifacts = new HashMap<>();
        EnchantedRegistry enchantedRegistry = new EnchantedRegistry(initialArtifacts);

        Runnable writerTask = () -> {
            enchantedRegistry.put("Sword of Destiny", "Legendary");
            enchantedRegistry.put("Shield of Ages", "Ancient");
            enchantedRegistry.remove("Sword of Destiny");
            System.out.println("Write operations completed.");
        };

