import java.util.*;
import java.util.concurrent.*;

class ChronomanticDragonTracker {

    private final Constellation<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    public synchronized Constellation<String, ImmutableOrb> getConstellations() {
        return deepClone(constellation).mapValues(ImmutableOrb::new);
    }

    public synchronized MutableOrb getOrb(String sigil) {
        if (constellation.containsKey(sigil)) {
            return new MutableOrb(constellation.get(sigil));
        }
        return null;
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (!constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found");
        }
        constellation.replace(sigil, new MutableOrb(shimmerX, shimmerY));
    }

    private static Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> original) {
        Map<String, MutableOrb> copy = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : original.entrySet()) {
            copy.put(entry.getKey(), new MutableOrb(entry.getValue()));
        }
        return new Constellation<>(copy);
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Constellation<String, MutableOrb> initialConstellation = new Constellation<>(
            Map.of("dragon1", new MutableOrb(10, 20), "dragon2", new MutableOrb(30, 40))
        );

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initialConstellation);

        Runnable task1 = () -> {
            try {
                tracker.setOrb("dragon1", 15, 25);
                System.out.println("Task 1 updated dragon1");
            } catch (IllegalArgumentException e) {
                System.err.println(e.getMessage());
            }
        };

        Runnable task2 = () -> {
            MutableOrb orb = tracker.getOrb("dragon2");
            if (orb != null) {
                System.out.println("Task 2 got orb: " + orb);
            } else {
                System.err.println("Task 2: Dragon not found");
            }
        };

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);

        Constellation<String, ImmutableOrb> result = tracker.getConstellations();
        for (Map.Entry<String, ImmutableOrb> entry : result.entrySet()) {
            System.out.println("Final position of " + entry.getKey() + ": " + entry.getValue());
        }
    }

    static class Constellation<K, V> extends HashMap<K, V> {}

    static class MutableOrb {
        private int shimmerX;
