        public MutableOrb(int shimmerX, int shimmerY) {
            this.shimmerX = shimmerX;
            this.shimmerY = shimmerY;
        }

        public MutableOrb(MutableOrb other) {
            this(other.shimmerX, other.shimmerY);
        }

        @Override
        public String toString() {
            return "MutableOrb{" + "shimmerX=" + shimmerX + ", shimmerY=" + shimmerY + '}';
        }
    }

    static class ImmutableOrb extends MutableOrb {

        private ImmutableOrb(MutableOrb other) {
            super(other);
        }

        public ImmutableOrb() {}

        @Override
        public void setShimmerX(int shimmerX) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void setShimmerY(int shimmerY) {
            throw new UnsupportedOperationException();
        }
    }
}

