        return orb == null ? null : new MutableOrb(orb.getX(), orb.getY());
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (!constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found");
        }
        constellation.put(sigil, new MutableOrb(shimmerX, shimmerY));
    }

    private static Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> original) {
        Map<String, MutableOrb> clonedMap = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : original.entrySet()) {
            clonedMap.put(entry.getKey(), new MutableOrb(entry.getValue().getX(), entry.getValue().getY()));
        }
        return new Constellation<>(clonedMap);
    }

    public static void main(String[] args) throws InterruptedException {
