        initialData.put("Draco", new MutableOrb(10, 20));
        initialData.put("Smaug", new MutableOrb(30, 40));

        Constellation<String, MutableOrb> initialConstellation = new Constellation<>(initialData);
        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initialConstellation);

