first = toAcct;
second = fromAcct;
}

synchronized (first) {
synchronized (second) {
if (fromAcct.getBalance() < amount.getValue())
throw new InsufficientFundsException();
fromAcct.setBalance(fromAcct.getBalance() - amount.getValue());
toAcct.setBalance(toAcct.getBalance() + amount.getValue());
}
}
