import java.math.BigDecimal;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class AccountTransfer {

    public static void main(String[] args) {
        Account accountA = new Account("Account A", 1000);
        Account accountB = new Account("Account B", 500);

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        Runnable transferTask1 = () -> {
            boolean result = accountA.transfer(accountB, new DollarAmount(200), 3, TimeUnit.SECONDS);
            if (!result) {
                System.out.println("Transfer from Account A to B failed.");
            }
        };

        Runnable transferTask2 = () -> {
            boolean result = accountB.transfer(accountA, new DollarAmount(300), 3, TimeUnit.SECONDS);
            if (!result) {
                System.out.println("Transfer from Account B to A failed.");
            }
        };

        executorService.submit(transferTask1);
        executorService.submit(transferTask2);

        executorService.shutdown();
    }

    static class Account {
        private final String name;
        private BigDecimal balance;
        private final Lock lock = new ReentrantLock();

        public Account(String name, BigDecimal initialBalance) {
            this.name = name;
            this.balance = initialBalance;
        }

        public boolean transfer(Account destination, DollarAmount amount, long timeout, TimeUnit unit) {
            boolean acquiredLocks = false;

            try {
                if (lock.tryLock(timeout, unit)) {
                    if (destination.lock.tryLock()) {
                        acquiredLocks = true;
                        if (balance.compareTo(amount.amount) >= 0) {
                            balance = balance.subtract(amount.amount);
                            destination.balance = destination.balance.add(amount.amount);
                            System.out.println("Transfer succeeded: " + amount.amount +
                                    " from " + name + " to " + destination.name);
                        } else {
                            throw new InsufficientFundsException(name, amount);
                        }
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                if (acquiredLocks) {
                    lock.unlock();
                    destination.lock.unlock();
                }
            }

            return acquiredLocks;
        }
    }

    static class DollarAmount {
        public final BigDecimal amount;

        public DollarAmount(BigDecimal amount) {
            this.amount = amount;
        }
    }

    static class InsufficientFundsException extends RuntimeException {
        public InsufficientFundsException(String accountName, DollarAmount amount) {
            super("Insufficient funds in " + accountName + " to transfer " + amount.amount);
        }
    }
}

import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class AccountTransfer {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Account account1 = new Account("Account 1", new DollarAmount(1000));
        Account account2 = new Account("Account 2", new DollarAmount(500));

        Runnable task1 = () -> transfer(account1, account2, new DollarAmount(300), 2, TimeUnit.SECONDS);
        Runnable task2 = () -> transfer(account2, account1, new DollarAmount(200), 2, TimeUnit.SECONDS);

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
    }

    public static boolean transfer(Account fromAccount, Account toAccount, DollarAmount amount, long timeout, TimeUnit timeUnit) {
        ReentrantLock lock1 = fromAccount.getLock();
        ReentrantLock lock2 = toAccount.getLock();

        if (lock1.getId() > lock2.getId()) {
            // Swap locks
            ReentrantLock temp = lock1;
            lock1 = lock2;
            lock2 = temp;
        }

        long nanosTimeout = timeUnit.toNanos(timeout);
        Random random = new Random();

        while (true) {
            boolean gotFirstLock = false;

            try {
                if (lock1.tryLock(nanosTimeout, TimeUnit.NANOSECONDS)) {
                    gotFirstLock = true;

                    if (lock2.tryLock(nanosTimeout - timeUnit.toNanos(lock1.getHoldCount()), TimeUnit.NANOSECONDS)) {
                        // Locks acquired
                        if (fromAccount.getAmount().compareTo(amount) >= 0) {
                            fromAccount.setAmount(fromAccount.getAmount().subtract(amount));
                            toAccount.setAmount(toAccount.getAmount().add(amount));
                            System.out.println("Transfer successful: " + amount);
                        } else {
                            throw new InsufficientFundsException();
                        }
                        return true;
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                if (gotFirstLock && lock1.isHeldByCurrentThread()) {
                    lock1.unlock();
                }
                if (lock2.isHeldByCurrentThread()) {
                    lock2.unlock();
                }
            }

            // Backoff strategy
            nanosTimeout = Math.min(nanosTimeout, timeUnit.toNanos(timeout));
            long delay = calculateFixedDelay() + random.nextInt(calculateRandomDelay());
            try {
                Thread.sleep(delay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private static long calculateFixedDelay() {
        return 100; // Fixed component of backoff in nanoseconds
    }

    private static int calculateRandomDelay() {
        return 2 * 10; // Random component range in nanoseconds (0-20)
    }

    static class Account {
        private final String name;
        private final DollarAmount amount;
        private final ReentrantLock lock = new ReentrantLock();

        public Account(String name, DollarAmount amount) {
            this.name = name;
            this.amount = amount;
        }

        public String getName() {
            return name;
        }

        public DollarAmount getAmount() {
            return amount;
        }

        public void setAmount(DollarAmount amount) {
            this.amount = amount;
        }

        public ReentrantLock getLock() {
            return lock;
        }
    }

    static class DollarAmount {
        private final long cents;

        public DollarAmount(long dollars) {
            this.cents = dollars * 100;
        }

        public long getCents() {
            return cents;
        }

        public DollarAmount subtract(DollarAmount other) {
            return new DollarAmount(this.cents - other.getCents());
        }

        public int compareTo(DollarAmount other) {
            return Long.compare(this.cents, other.getCents());
        }
    }

    static class InsufficientFundsException extends RuntimeException {
        public InsufficientFundsException() {
            super("Insufficient funds for the transfer");
        }
    }
}

import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.TimeUnit;
import java.util.Random;

public class Bank {

    public static void main(String[] args) {
        Account account1 = new Account("Account1", 1000);
        Account account2 = new Account("Account2", 500);

        Executor executor = new Executor();

        Runnable transferTask1 = () -> {
            boolean success = executeTransfer(account1, account2, 300, 5, TimeUnit.SECONDS);
            System.out.println(success ? "Transfer from Account1 to Account2 succeeded" : "Transfer from Account1 to Account2 failed");
        };

        Runnable transferTask2 = () -> {
            boolean success = executeTransfer(account2, account1, 700, 5, TimeUnit.SECONDS);
            System.out.println(success ? "Transfer from Account2 to Account1 succeeded" : "Transfer from Account2 to Account1 failed");
        };

        executor.execute(transferTask1);
        executor.execute(transferTask2);

        executor.shutdown();
    }

    public static boolean executeTransfer(Account sourceAccount, Account destinationAccount, int amount, long timeout, TimeUnit unit) {
        if (tryLockAndExecute(sourceAccount, destinationAccount, amount, timeout, unit)) {
            return true;
        }
        return false;
    }

    private static boolean tryLockAndExecute(Account src, Account dest, int amount, long timeout, TimeUnit timeUnit) {
        Random random = new Random();

        for (int i = 0; i < 3; i++) {
            boolean lock1Acquired = src.lock.tryLock(timeout, timeUnit);
            boolean lock2Acquired = dest.lock.tryLock(timeout, timeUnit);

            if (lock1Acquired && lock2Acquired) {
                try {
                    if (src.amount >= amount) {
                        src.withdraw(amount);
                        dest.deposit(amount);
                        return true;
                    } else {
                        throw new InsufficientFundsException("Insufficient funds for transfer");
                    }
                } catch (InsufficientFundsException e) {
                    System.out.println(e.getMessage());
                } finally {
                    src.lock.unlock();
                    dest.lock.unlock();
                }
            } else {
                if (!lock1Acquired || !lock2Acquired) {
                    long delay = calculateRandomBackoff(i, random);
                    try {
                        TimeUnit.MILLISECONDS.sleep(delay);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }

        return false;
    }

    private static long calculateFixedDelay(int attempt) {
        return 100L * attempt; // fixed delay of 100ms per attempt
    }

    private static long calculateRandomBackoff(int attempt, Random random) {
        long baseDelay = calculateFixedDelay(attempt);
        long randomComponent = random.nextInt(3); // random component between 0 and 2
        return baseDelay + (randomComponent * 50L); // additional delay of up to 100ms
    }

    static class Account {
        final ReentrantLock lock = new ReentrantLock();
        final String name;
        DollarAmount amount;

        public Account(String name, int amount) {
            this.name = name;
            this.amount = new DollarAmount(amount);
        }

        void deposit(int amount) {
            this.amount.add(new DollarAmount(amount));
        }

        void withdraw(int amount) throws InsufficientFundsException {
            if (this.amount.get() >= amount) {
                this.amount.subtract(new DollarAmount(amount));
            } else {
                throw new InsufficientFundsException("Insufficient funds to withdraw");
            }
        }
