import java.awt.Point;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class DelegatingVehicleTracker {

    private final ConcurrentHashMap<String, Point> vehicleLocations = new ConcurrentHashMap<>();

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        vehicleLocations.putAll(initialLocations);
    }

    public Map<String, Point> getLocations() {
        return vehicleLocations.entrySet()
                .stream()
                .collect(Collectors.toUnmodifiableMap(Map.Entry::getKey, Map.Entry::getValue));
    }

    public Point getLocation(String id) {
        return vehicleLocations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (!vehicleLocations.containsKey(id)) {
            throw new IllegalArgumentException("Vehicle ID does not exist");
        }
        vehicleLocations.put(id, new Point(x, y));
    }

    public Map<String, Point> getLocationsAsStatic() {
        return vehicleLocations.entrySet()
                .stream()
                .collect(Collectors.toUnmodifiableMap(Map.Entry::getKey, Map.Entry::getValue));
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(5);
        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(Map.of(
                "Car1", new Point(0, 0),
                "Car2", new Point(10, 20)
        ));

        Runnable task1 = () -> {
            System.out.println("Task1: Updating Car1 location");
            tracker.setLocation("Car1", 5, 5);
        };

        Runnable task2 = () -> {
            System.out.println("Task2: Getting location of Car2");
            Point loc = tracker.getLocation("Car2");
            System.out.println("Location of Car2: " + (loc != null ? loc : "Not found"));
        };

        Runnable task3 = () -> {
            System.out.println("Task3: Attempting to update non-existent Car3");
            try {
                tracker.setLocation("Car3", 15, 25);
            } catch (IllegalArgumentException e) {
                System.out.println(e.getMessage());
            }
        };

        Runnable task4 = () -> {
            System.out.println("Task4: Getting all locations");
            Map<String, Point> locations = tracker.getLocations();
            System.out.println("All Locations: " + locations);
        };

        executor.execute(task1);
        executor.execute(task2);
        executor.execute(task3);
        executor.execute(task4);

        Runnable task5 = () -> {
            System.out.println("Task5: Getting static snapshot of all locations");
            Map<String, Point> snapshot = tracker.getLocationsAsStatic();
            System.out.println("Snapshot Locations: " + snapshot);
        };

        executor.execute(task5);

        executor.shutdown();
    }
}

