import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class StripedMap<K, V> {

    private static final int N_LOCKS = 16;
    private final Node<K, V>[] buckets;
    private final ReentrantLock[] locks;

    public StripedMap(int initialCapacity) {
        this.buckets = new Node[initialCapacity];
        this.locks = new ReentrantLock[N_LOCKS];

        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new ReentrantLock();
        }
    }

    private int hashIndex(int hashCode) {
        return Math.abs(hashCode % buckets.length);
    }

    public V get(K key) {
        int index = hashIndex(key.hashCode());
        final ReentrantLock lock = locks[index % N_LOCKS];
        lock.lock();
        try {
            Node<K, V> node = buckets[index];
            while (node != null) {
                if (key.equals(node.key)) {
                    return node.value;
                }
                node = node.next;
            }
            return null;
        } finally {
            lock.unlock();
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            final ReentrantLock lock = locks[i % N_LOCKS];
            lock.lock();
            try {
                buckets[i] = null;
            } finally {
                lock.unlock();
            }
        }
    }

    public static class Node<K, V> {
        final K key;
        final V value;
        Node<K, V> next;

        Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

