import java.math.BigInteger;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ImmutableFactorCache {

    private final BigInteger number;
    private final BigInteger[] factors;

    public ImmutableFactorCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = factors.clone();
    }

    public BigInteger[] getFactors(BigInteger inputNumber) {
        if (this.number.equals(inputNumber)) {
            return this.factors.clone();
        }
        return null;
    }

    private void computeAndCacheFactors(BigInteger number) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Future<BigInteger[]> future = executor.submit(() -> {
                BigInteger sqrt = number.sqrt();
                BigInteger[] factorsList = new BigInteger[3];
                int count = 0;

                for (BigInteger i = BigInteger.ONE; i.compareTo(sqrt) <= 0 && count < 3; i = i.add(BigInteger.ONE)) {
                    if (number.mod(i).equals(BigInteger.ZERO)) {
                        factorsList[count++] = i;
                        if (!i.equals(number.divide(i))) {
                            factorsList[count++] = number.divide(i);
                        }
                    }
                }

                return factorsList;
            });

            BigInteger[] result = future.get();
            new ImmutableFactorCache(number, result);
        } finally {
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.SECONDS);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        BigInteger numberToCache = new BigInteger("15");

        ImmutableFactorCache cache = new ImmutableFactorCache(numberToCache, computeFactors(numberToCache));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Future<BigInteger[]> future1 = executor.submit(() -> cache.getFactors(new BigInteger("15")));
            Future<BigInteger[]> future2 = executor.submit(() -> cache.getFactors(new BigInteger("10")));

            System.out.println(java.util.Arrays.toString(future1.get()));
            System.out.println(java.util.Arrays.toString(future2.get()));

        } finally {
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.SECONDS);
        }
    }

    private static BigInteger[] computeFactors(BigInteger number) throws InterruptedException {
        ImmutableFactorCache cache = new ImmutableFactorCache(number, new BigInteger[0]);
        cache.computeAndCacheFactors(number);

        if (number.equals(new BigInteger("15"))) {
            return new BigInteger[]{BigInteger.ONE, new BigInteger("3"), new BigInteger("5")};
        }
        return new BigInteger[0];
    }
}

