    private static BigInteger[] calculateFactors(BigInteger number) {
        BigInteger sqrt = number.sqrt();
        BigInteger[] factors = new BigInteger[2];

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<BigInteger> future;

        Callable<BigInteger> task = () -> {
            for (BigInteger i = BigInteger.ONE; i.compareTo(sqrt) <= 0; i = i.add(BigInteger.ONE)) {
