            BigInteger factor1 = future.get();
            if (factor1 != null) {
                factors[0] = factor1;
                factors[1] = number.divide(factor1);
                return factors;
            }
        } catch (Exception e) {
            // Handle exception
        }

        executor.shutdown();
        return new BigInteger[]{number, BigInteger.ONE};
    }

