import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicReference;

public class NonBlockingStack<T> {
    private static final class Node<E> {
        final E item;
        final AtomicReference<Node<E>> next;

        Node(E element, Node<E> next) {
            this.item = element;
            this.next = new AtomicReference<>(next);
        }
    }

    private final AtomicReference<Node<T>> top = new AtomicReference<>();

    public void push(T item) {
        Node<T> newHead = new Node<>(item, null);
        while (true) {
            Node<T> currentTop = top.get();
            newHead.next.set(currentTop);
            if (top.compareAndSet(currentTop, newHead)) {
                break;
            }
        }
    }

    public T pop() {
        while (true) {
            Node<T> currentTop = top.get();
            if (currentTop == null) {
                return null; // Stack is empty
            }
            Node<T> nextNode = currentTop.next.get();
            if (top.compareAndSet(currentTop, nextNode)) {
                return currentTop.item;
            }
        }
    }

