import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class ArkLoader {

    enum Gender {
        MALE, FEMALE
    }

    static class Animal implements Comparable<Animal> {
        private final String species;
        private final Gender gender;

        public Animal(String species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }

        public String getSpecies() {
            return species;
        }

        public Gender getGender() {
            return gender;
        }

        @Override
        public int compareTo(Animal other) {
            int speciesComparison = this.species.compareTo(other.species);
            if (speciesComparison != 0) {
                return speciesComparison;
            }
            return this.gender == Gender.FEMALE ? -1 : 1; // Sort females before males
        }
    }

    static class AnimalPair {
        private final Animal animal1;
        private final Animal animal2;

        public AnimalPair(Animal animal1, Animal animal2) {
            this.animal1 = animal1;
            this.animal2 = animal2;
        }

        @Override
        public String toString() {
            return "Pair: (" + animal1.getSpecies() + ", " + animal1.getGender() + ") and ("
                    + animal2.getSpecies() + ", " + animal2.getGender() + ")";
        }
    }

    static class Ark {
        private final List<AnimalPair> pairs = new ArrayList<>();

        public synchronized void addPair(AnimalPair pair) {
            pairs.add(pair);
        }

        public synchronized int getNumberOfPairs() {
            return pairs.size();
        }
    }

    public static int loadTheArk(Collection<Animal> animals) throws InterruptedException, ExecutionException {
        Animal[] animalArray = animals.toArray(new Animal[0]);
        Arrays.sort(animalArray);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Ark ark = new Ark();

        for (int i = 0; i < animalArray.length - 1; i++) {
            final int index = i;
            executor.submit(() -> {
                Animal currentAnimal = animalArray[index];
                if (index + 1 < animalArray.length) {
                    Animal nextAnimal = animalArray[index + 1];
                    if (currentAnimal.getSpecies().equals(nextAnimal.getSpecies()) &&
                            currentAnimal.getGender() != nextAnimal.getGender()) {
                        ark.addPair(new AnimalPair(currentAnimal, nextAnimal));
                    }
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
        return ark.getNumberOfPairs();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Animal> animals = Arrays.asList(
                new Animal("Lion", Gender.MALE),
                new Animal("Lion", Gender.FEMALE),
                new Animal("Elephant", Gender.MALE),
                new Animal("Elephant", Gender.FEMALE)
        );

        int pairs = loadTheArk(animals);
        System.out.println("Number of valid pairs: " + pairs);
    }
}

