    public static int loadTheArk(Collection<Animal> animals) throws InterruptedException, ExecutionException {
        Ark ark = new Ark();

        // Sort the animals by species and then by gender
        List<Animal> sortedAnimals = new ArrayList<>(animals);
        sortedAnimals.sort(Comparator.comparingInt(a -> a.getSpecies().ordinal())
                .thenComparingInt(a -> a.getGender().ordinal()));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Pair animals concurrently
        for (int i = 0; i < sortedAnimals.size() - 1; i++) {
            final int index = i;
            executor.submit(() -> {
                Animal currentAnimal = sortedAnimals.get(index);
                if (index + 1 < sortedAnimals.size()) {
                    Animal nextAnimal = sortedAnimals.get(index + 1);
                    if (canPair(currentAnimal, nextAnimal)) {
