        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);

        return ark.getNumberOfPairs();
    }

    private static boolean canPair(Animal a1, Animal a2) {
        return a1.getSpecies() == a2.getSpecies() && a1.getGender() != a2.getGender();
