import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class ArkLoader {

    enum Gender {
        MALE, FEMALE
    }

    enum Species {
        LION, TIGER, ELEPHANT, GIRAFFE
    }

    static class Animal implements Comparable<Animal> {
        private final Species species;
        private final Gender gender;

        public Animal(Species species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }

        public Species getSpecies() {
            return species;
        }

        public Gender getGender() {
            return gender;
        }

        @Override
        public int compareTo(Animal other) {
            int speciesComparison = this.species.compareTo(other.species);
            if (speciesComparison != 0) {
                return speciesComparison;
            }
            return this.gender == Gender.MALE ? -1 : 1; // MALE before FEMALE for pairing
        }

        @Override
        public String toString() {
            return species + " (" + gender + ")";
        }
    }

    static class AnimalPair {
        private final Animal male;
        private final Animal female;

        public AnimalPair(Animal male, Animal female) {
            this.male = male;
            this.female = female;
        }

        @Override
        public String toString() {
            return "(" + male + ", " + female + ")";
        }
    }

    static class Ark {
        private final List<AnimalPair> pairs = Collections.synchronizedList(new ArrayList<>());

        public void addPair(AnimalPair pair) {
            pairs.add(pair);
        }

        @Override
        public String toString() {
            return "Ark{" + "pairs=" + pairs + '}';
        }
    }

    public static int loadTheArk(Collection<Animal> animals) throws InterruptedException, ExecutionException {
        animals = animals.stream()
                .sorted()
                .collect(Collectors.toList());

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Ark ark = new Ark();

        while (animals.size() > 1) {
            Animal male = null;
            Animal female = null;

            for (Iterator<Animal> iterator = animals.iterator(); iterator.hasNext(); ) {
                Animal animal = iterator.next();
                if (male == null && animal.getGender() == Gender.MALE) {
                    male = animal;
                    iterator.remove();
                } else if (female == null && animal.getGender() == Gender.FEMALE &&
                        male != null && animal.getSpecies().equals(male.getSpecies())) {
                    female = animal;
                    iterator.remove();
                    break;
                }
            }

            if (male != null && female != null) {
                Future<?> future = executor.submit(() -> ark.addPair(new AnimalPair(male, female)));
                future.get(); // Wait for the task to complete
            } else {
                break; // No more pairs can be formed
            }
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);
        return ark.toString().chars().filter(ch -> ch == '(').count() / 2;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Animal> animals = Arrays.asList(
                new Animal(Species.LION, Gender.MALE),
                new Animal(Species.LION, Gender.FEMALE),
                new Animal(Species.TIGER, Gender.MALE),
                new Animal(Species.TIGER, Gender.FEMALE),
                new Animal(Species.ELEPHANT, Gender.MALE)
        );

        int pairs = loadTheArk(animals);
        System.out.println("Number of pairs: " + pairs);
    }
}

