import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class PrimeProducerConsumer {

    private static final int PRIME_COUNT = 2;

    public static void main(String[] args) {
        BlockingQueue<Integer> queue = new LinkedBlockingQueue<>();

        Producer producer = new Producer(queue, PRIME_COUNT);
        Consumer consumer = new Consumer(queue);

        Thread producerThread = new Thread(producer);
        Thread consumerThread = new Thread(consumer);

        producerThread.start();
        consumerThread.start();

        try {
            consumerThread.join();
            producer.interrupt();  // Signal producer to stop
            producerThread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();  // Restore interrupted status
        }
    }

    static class Producer implements Runnable {
        private final BlockingQueue<Integer> queue;
        private final int primeCount;

        public Producer(BlockingQueue<Integer> queue, int primeCount) {
            this.queue = queue;
            this.primeCount = primeCount;
        }

        @Override
        public void run() {
            try {
                for (int i = 2; i < PRIME_COUNT + 2; i++) {
                    if (Thread.currentThread().isInterrupted()) break;

                    while (!queue.offer(isPrime(i))) {
                        if (Thread.currentThread().isInterrupted()) return;
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        private boolean isPrime(int num) {
            if (num < 2) return false;
            for (int i = 2; i <= Math.sqrt(num); i++) {
                if (num % i == 0) return false;
            }
            return true;
        }
    }

    static class Consumer implements Runnable {
        private final BlockingQueue<Integer> queue;

        public Consumer(BlockingQueue<Integer> queue) {
            this.queue = queue;
        }

        @Override
        public void run() {
            try {
                for (int i = 0; i < PRIME_COUNT; i++) {
                    Integer prime = queue.take();
                    System.out.println("Consumed: " + prime);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

