interface Element {
    int compute();
}

class Node implements Element {
    private final List<Node> children = new ArrayList<>();

    public void addChild(Node child) {
        children.add(child);
    }

    public List<Node> getChildren() {
        return children;
    }

    @Override
    public int compute() {
        int result = 1; // Base computation for the node itself.
        for (Node child : children) {
            result += child.compute();
        }
        return result;
    }
}

public class ParallelExecution {

    private static final ExecutorService executor = Executors.newFixedThreadPool(2);

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Node root = new Node();
        Node child1 = new Node();
        Node child2 = new Node();
        root.addChild(child1);
        root.addChild(child2);

        List<Node> nodes = new ArrayList<>();
        nodes.add(root);
        nodes.add(child1);
        nodes.add(child2);

        // Sequential processing
        System.out.println("Sequential: " + sequentialProcess(nodes));

        // Parallel processing using ExecutorService
        System.out.println("Parallel: " + parallelProcess(nodes));
    }

    public static int sequentialProcess(List<Node> elements) {
        int result = 0;
        for (Node element : elements) {
            result += element.compute();
        }
        return result;
    }

    public static int parallelProcess(List<Node> elements) throws InterruptedException, ExecutionException {
        List<Future<Integer>> futures = new ArrayList<>();
        for (Node element : elements) {
            Future<Integer> future = executor.submit(() -> element.compute());
            futures.add(future);
        }

        int result = 0;
        for (Future<Integer> future : futures) {
            result += future.get();
        }
        return result;
    }

    public static int recursiveSequentialProcess(Node node) {
        int result = node.compute();
        for (Node child : node.getChildren()) {
            result += recursiveSequentialProcess(child);
        }
        return result;
    }

    public static int recursiveParallelProcess(Node node) throws InterruptedException, ExecutionException {
        List<Future<Integer>> futures = new ArrayList<>();
        for (Node child : node.getChildren()) {
            Future<Integer> future = executor.submit(() -> recursiveParallelProcess(child));
            futures.add(future);
        }

        int result = node.compute();
        for (Future<Integer> future : futures) {
            result += future.get();
        }
        return result;
    }
