import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadWriteMap<K, V> {

    private final Map<K, V> map;
    private final ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public void put(K key, V value) {
        rwl.writeLock().lock();
        try {
            map.put(key, value);
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public V get(K key) {
        rwl.readLock().lock();
        try {
            return map.get(key);
        } finally {
            rwl.readLock().unlock();
        }
    }

    public void remove(Object key) {
        rwl.writeLock().lock();
        try {
            map.remove(key);
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        rwl.writeLock().lock();
        try {
            map.putAll(m);
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public void clear() {
        rwl.writeLock().lock();
        try {
            map.clear();
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public int size() {
        rwl.readLock().lock();
        try {
            return map.size();
        } finally {
            rwl.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        rwl.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            rwl.readLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        rwl.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            rwl.readLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        rwl.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            rwl.readLock().unlock();
        }
    }

    class WriterTask implements Runnable {
        private final K key;
        private final V value;

        WriterTask(K key, V value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public void run() {
            ReadWriteMap.this.put(key, value);
        }
    }

    class ReaderTask implements Runnable {
        private final K key;

        ReaderTask(K key) {
            this.key = key;
        }

        @Override
        public void run() {
            System.out.println("Value for " + key + ": " + ReadWriteMap.this.get(key));
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Map<Integer, String> initialMap = new HashMap<>();
        ReadWriteMap<Integer, String> rwMap = new ReadWriteMap<>(initialMap);

        Thread writer1 = new Thread(rwMap.new WriterTask(1, "One"));
        Thread writer2 = new Thread(rwMap.new WriterTask(2, "Two"));

        Thread reader1 = new Thread(rwMap.new ReaderTask(1));
        Thread reader2 = new Thread(rwMap.new ReaderTask(2));

        writer1.start();
        writer2.start();

        writer1.join();
        writer2.join();

        reader1.start();
        reader2.start();

        reader1.join();
        reader2.join();
    }
}

